@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService service;

    public OrderController(OrderService service) {
        this.service = service;
    }

    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id, Authentication auth) {
        if (auth == null) {
            // 401: the server does not know who you are (missing/invalid credentials)
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
        var order = service.findById(id).orElseThrow();
        if (!order.ownerId().equals(auth.getName())) {
            // 403: authenticated, but not allowed to touch this resource
            return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
        }
        return ResponseEntity.ok(order);
    }
}
